import{createApp,watch}from"vue";import{createPinia}from"pinia";import{useAddressSettingsStore}from"../vue/stores/AddressSettingsStore";import{useAddressStore}from"../vue/stores/AddressStore";import AddressSettingsHydrator from"./address-settings-hydrator";function ensureEmptyChildMount(container,className){let mountEl=container.querySelector(`.${className}`);if(!mountEl){mountEl=document.createElement("div");mountEl.className=className;mountEl.style.display="contents";container.appendChild(mountEl);return mountEl}if(mountEl.childNodes.length){const fresh=document.createElement("div");fresh.style.display="contents";mountEl.appendChild(fresh);return fresh}return mountEl}function safeParseJson(value,fallback={}){try{return JSON.parse(value)}catch(e){return fallback}}function initAddressSettings(rootEl){if(!rootEl){console.warn("[GM] initAddressSettings called without a rootEl");return}if(rootEl.__gmSettingsInitialized){return}rootEl.__gmSettingsInitialized=true;const pinia=createPinia();const previewRoot=rootEl.querySelector("[data-gm-preview-root]");if(previewRoot){const previewMount=ensureEmptyChildMount(previewRoot,"gm-address-vue-root");const addressRoot=previewRoot.querySelector("[data-gm-address-root]")||previewRoot;const baseConfig=safeParseJson(addressRoot.dataset?.config,{});baseConfig.namespace??={};const id=baseConfig.namespace.id||previewRoot.id||"gm-preview";baseConfig.namespace.id=id;previewRoot.id||=id;const previewApp=createApp(AddressSettingsHydrator,{rootEl:addressRoot,config:baseConfig});previewApp.use(pinia);previewApp.mount(previewMount)}else{console.warn("[GM] No [data-gm-preview-root] found under settings root")}const settingsWrapper=rootEl.querySelector("[data-gm-settings-vue-mount]")||rootEl;const settingsMount=ensureEmptyChildMount(settingsWrapper,"gm-settings-vue-root");const settingsApp=createApp({setup(){const settings=useAddressSettingsStore();const address=useAddressStore();settings.setFromDom(rootEl);settings.bindDomListeners(rootEl);watch(()=>settings.previewConfig,config=>{if(!config){return}if(typeof address.applySettings==="function"){address.applySettings(config)}},{deep:true,immediate:true});watch(()=>address?.data?.coords,coords=>{if(!coords){return}const setVal=(path,val)=>{const el=rootEl.querySelector(`[name$="${path}"]`);if(!el){return}const next=String(val??"");if(el.value===next){return}el.value=next;el.dispatchEvent(new Event("input",{bubbles:true}));el.dispatchEvent(new Event("change",{bubbles:true}))};setVal("[coordinatesDefault][lat]",coords.lat);setVal("[coordinatesDefault][lng]",coords.lng);setVal("[coordinatesDefault][zoom]",coords.zoom)},{deep:true});return{}},template:"<div></div>"});settingsApp.use(pinia);settingsApp.mount(settingsMount)}window.initAddressSettings=initAddressSettings;export default initAddressSettings;(function(){const boot=()=>{document.querySelectorAll("[data-gm-settings-root]").forEach(initAddressSettings)};if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",boot,{once:true})}else{boot()}})();